-- Server time avoids caller clock manipulation. Members are generated by the server.
local time=redis.call('TIME');local now=tonumber(time[1])*1000+math.floor(tonumber(time[2])/1000)
redis.call('ZREMRANGEBYSCORE',KEYS[1],'-inf',now-tonumber(ARGV[1]))
if ARGV[3]=='ONCE' then redis.call('ZADD',KEYS[1],'NX',now,ARGV[2])
else redis.call('ZADD',KEYS[1],now,ARGV[2]) end
redis.call('PEXPIRE',KEYS[1],tonumber(ARGV[1])+1000)
return redis.call('ZCARD',KEYS[1])
